}

int configure(int argc, char **argv)
{
	int c;

	while ((c = getopt(argc, argv, "hvb")) != -1) {
		switch (c) {
		case 'h':
			help(argv[0]);
			return 1;
		case 'v':
			version(argv[0]);
			return 1;
		case 'b':
			break;
		case '?':
		default:
			return 1;
		}
	}

	return 0;
}

