// Copyright K Cartlidge, 2026.   AGPL - see LICENCE.txt

package source

import (
	"errors"
	"fmt"
	"sort"
	"strconv"
	"strings"
)

// FixupKind identifies placeholder patch kinds.
type FixupKind string

const (
	FixupImm8  FixupKind = "imm8"
	FixupImm16 FixupKind = "imm16"
	FixupRel8  FixupKind = "rel8"
)

// Fixup stores a queued patch request for unresolved values.
type Fixup struct {
	Offset      int       `json:"offset"`
	Kind        FixupKind `json:"kind"`
	Expr        *ExprNode `json:"expr,omitempty"`
	SourceLine  int       `json:"sourceLine"`
	OutputLine  int       `json:"outputLine"`
	SourceStack string    `json:"sourceStack,omitempty"`
	RelativeTo  uint16    `json:"relativeTo,omitempty"` // For rel8 this is PC after operand byte.
}

// ListingEntry stores per-statement byte-location metadata for listing output.
type ListingEntry struct {
	OutputLine int           `json:"outputLine"`
	SourceLine int           `json:"sourceLine"`
	Kind       StatementKind `json:"kind"`
	LC         uint16        `json:"lc"`
	ByteOffset int           `json:"byteOffset"`
	ByteCount  int           `json:"byteCount"`
	IncbinFile string        `json:"incbinFile,omitempty"` // basename only; when set, bytes listing shows file + count instead of hex
	Operator   string        `json:"operator,omitempty"`
	OpText     string        `json:"opText,omitempty"`
	Template   string        `json:"template,omitempty"`
	ByteTpl    string        `json:"byteTemplate,omitempty"`
}

// EncodeResult stores emitted bytes and queued fixups.
type EncodeResult struct {
	Bytes        []byte            `json:"bytes"`
	Fixups       []Fixup           `json:"fixups"`
	SymbolValues map[string]uint16 `json:"symbolValues"`
	Listing      []ListingEntry    `json:"listing"`
	Warnings     []string          `json:"warnings,omitempty"`
	// LoadAddress is where the first byte of the binary maps in memory (0 if no bytes and no ORG).
	// EntryAddress is the execution start for loaders and metadata (USR address on TAP).
	LoadAddress  uint16 `json:"loadAddress"`
	EntryAddress uint16 `json:"entryAddress"`
}

// orgEntryState tracks ORG / ENTRY directives (at most one of each).
type orgEntryState struct {
	orgCount, entryCount int
	orgSeen              bool
	orgAddr              uint16
	entrySeen            bool
	entryAddr            uint16
	loadRecorded         bool
	firstLoadLC          uint16
}

func (s *orgEntryState) recordFirstLoad(lc uint16) {
	if !s.loadRecorded {
		s.loadRecorded = true
		s.firstLoadLC = lc
	}
}

func (s *orgEntryState) finalizeLoad() uint16 {
	if s.loadRecorded {
		return s.firstLoadLC
	}
	if s.orgSeen {
		return s.orgAddr
	}
	return 0
}

func (s *orgEntryState) finalizeEntry(loadAddr uint16) uint16 {
	if s.entrySeen {
		return s.entryAddr
	}
	if s.orgSeen {
		return s.orgAddr
	}
	if s.loadRecorded {
		return loadAddr
	}
	return 0
}

// Encode walks parsed/classified source and emits bytes using a single 16-bit LC.
func Encode(src ParsedSource, classified ClassifiedSource, defs Definitions) (EncodeResult, error) {
	var out EncodeResult
	out.Bytes = make([]byte, 0, 1024)
	out.Fixups = make([]Fixup, 0, 16)
	out.Listing = make([]ListingEntry, 0, len(src.Statements))
	out.Warnings = make([]string, 0, 2)

	errs := make([]string, 0, 8)
	symbolValues := make(map[string]uint16, len(defs.ByName))

	classifiedIndex := 0
	lc := uint16(0)
	var oe orgEntryState

	for _, stmt := range src.Statements {
		lcBefore := lc
		byteOffsetBefore := len(out.Bytes)

		cstmt := ClassifiedStatement{
			OutputLine: stmt.OutputLine,
			SourceLine: stmt.SourceLine,
			Operands:   nil,
		}
		if len(stmt.Operands) > 0 {
			if classifiedIndex >= len(classified.Statements) {
				errs = append(errs, formatDiagnosticBlock(formatStatementOrigin(stmt, src.FileDisplayNames), "missing classified operands"))
				continue
			}
			cstmt = classified.Statements[classifiedIndex]
			classifiedIndex++
		}

		if stmt.Label != "" && !(stmt.Kind == StatementDirective && (stmt.Operator == "EQU" || stmt.Operator == "SET")) {
			symbolValues[strings.ToUpper(stmt.Label)] = lc
		}

		incbinListingFile := ""
		if stmt.Kind == StatementDirective && stmt.Operator == "END" && len(cstmt.Operands) > 0 {
			out.Warnings = append(out.Warnings, formatDiagnosticBlock(formatStatementOrigin(stmt, src.FileDisplayNames), "END directive has entry address, which we ignore (use ENTRY for execution start)"))
		}
		switch stmt.Kind {
		case StatementDirective:
			var err error
			incbinListingFile, err = encodeDirective(stmt, cstmt, &lc, symbolValues, &out, &oe)
			if err != nil {
				errs = append(errs, formatDiagnosticBlock(formatStatementOrigin(stmt, src.FileDisplayNames), err.Error()))
			}
		case StatementData:
			if err := encodeData(stmt, cstmt, &lc, symbolValues, &out); err != nil {
				errs = append(errs, formatDiagnosticBlock(formatStatementOrigin(stmt, src.FileDisplayNames), err.Error()))
			}
		case StatementOperation:
			match, err := encodeOperation(stmt, cstmt, &lc, symbolValues, &out)
			if err != nil {
				errs = append(errs, formatDiagnosticBlock(formatStatementOrigin(stmt, src.FileDisplayNames), err.Error()))
			} else {
				list := ListingEntry{
					OutputLine: stmt.OutputLine,
					SourceLine: stmt.SourceLine,
					Kind:       stmt.Kind,
					LC:         lcBefore,
					ByteOffset: byteOffsetBefore,
					ByteCount:  len(out.Bytes) - byteOffsetBefore,
					Operator:   stmt.Operator,
					OpText:     match.OpText,
					Template:   match.Template,
					ByteTpl:    match.ByteTemplate,
				}
				out.Listing = append(out.Listing, list)
				if len(out.Bytes) > byteOffsetBefore {
					oe.recordFirstLoad(lcBefore)
				}
				continue
			}
		}

		out.Listing = append(out.Listing, ListingEntry{
			OutputLine: stmt.OutputLine,
			SourceLine: stmt.SourceLine,
			Kind:       stmt.Kind,
			LC:         lcBefore,
			ByteOffset: byteOffsetBefore,
			ByteCount:  len(out.Bytes) - byteOffsetBefore,
			IncbinFile: incbinListingFile,
		})

		if len(out.Bytes) > byteOffsetBefore {
			oe.recordFirstLoad(lcBefore)
		}
	}

	if len(errs) > 0 {
		return out, errors.New(strings.Join(errs, ""))
	}
	sort.SliceStable(out.Listing, func(i, j int) bool {
		return out.Listing[i].OutputLine < out.Listing[j].OutputLine
	})
	out.SymbolValues = copySymbolValues(symbolValues)
	out.LoadAddress = oe.finalizeLoad()
	out.EntryAddress = oe.finalizeEntry(out.LoadAddress)
	if oe.entrySeen && len(out.Bytes) > 0 {
		lo := int64(out.LoadAddress)
		ent := int64(out.EntryAddress)
		if ent < lo || ent >= lo+int64(len(out.Bytes)) {
			return out, fmt.Errorf("ENTRY $%04X outside loaded binary at $%04X (%d bytes)", out.EntryAddress, out.LoadAddress, len(out.Bytes))
		}
	}
	return out, nil
}

// ResolveFixups patches unresolved placeholders after encode and enforces range checks.
func ResolveFixups(src ParsedSource, classified ClassifiedSource, encoded EncodeResult) ([]byte, error) {
	symbolValues := copySymbolValues(encoded.SymbolValues)
	bytesOut := append([]byte(nil), encoded.Bytes...)

	if err := resolveEquSetSymbols(src, classified, symbolValues); err != nil {
		return nil, err
	}

	errs := make([]string, 0, 8)
	for _, fix := range encoded.Fixups {
		if fix.Expr == nil {
			errs = append(errs, formatDiagnosticBlock(formatFixupOrigin(fix, src.FileDisplayNames), "fixup has empty expression"))
			continue
		}
		value, known, err := evalExprWithCurrentLC(fix.Expr, symbolValues, fix.RelativeTo)
		if err != nil {
			errs = append(errs, formatDiagnosticBlock(formatFixupOrigin(fix, src.FileDisplayNames), err.Error()))
			continue
		}
		if !known {
			errs = append(errs, formatDiagnosticBlock(formatFixupOrigin(fix, src.FileDisplayNames), "unresolved symbol in fixup expression"))
			continue
		}
		if fix.Offset < 0 || fix.Offset >= len(bytesOut) {
			errs = append(errs, formatDiagnosticBlock(formatFixupOrigin(fix, src.FileDisplayNames), "fixup offset out of range"))
			continue
		}

		switch fix.Kind {
		case FixupImm8:
			if value < 0 || value > 0xFF {
				errs = append(errs, formatDiagnosticBlock(formatFixupOrigin(fix, src.FileDisplayNames), fmt.Sprintf("imm8 out of range: %d", value)))
				continue
			}
			bytesOut[fix.Offset] = byte(value)
		case FixupImm16:
			if value < 0 || value > 0xFFFF {
				errs = append(errs, formatDiagnosticBlock(formatFixupOrigin(fix, src.FileDisplayNames), fmt.Sprintf("imm16 out of range: %d", value)))
				continue
			}
			if fix.Offset+1 >= len(bytesOut) {
				errs = append(errs, formatDiagnosticBlock(formatFixupOrigin(fix, src.FileDisplayNames), "imm16 fixup offset out of range"))
				continue
			}
			bytesOut[fix.Offset] = byte(value)
			bytesOut[fix.Offset+1] = byte(value >> 8)
		case FixupRel8:
			delta := value - int64(fix.RelativeTo)
			if delta < -128 || delta > 127 {
				errs = append(errs, formatDiagnosticBlock(formatFixupOrigin(fix, src.FileDisplayNames), fmt.Sprintf("rel8 out of range: %d", delta)))
				continue
			}
			bytesOut[fix.Offset] = byte(int8(delta))
		default:
			errs = append(errs, formatDiagnosticBlock(formatFixupOrigin(fix, src.FileDisplayNames), fmt.Sprintf("unsupported fixup kind `%s`", fix.Kind)))
		}
	}

	if len(errs) > 0 {
		return nil, errors.New(strings.Join(errs, ""))
	}
	return bytesOut, nil
}

// ResolveSymbolValues returns final symbol values after EQU/SET resolution.
func ResolveSymbolValues(src ParsedSource, classified ClassifiedSource, encoded EncodeResult) (map[string]uint16, error) {
	symbolValues := copySymbolValues(encoded.SymbolValues)
	if err := resolveEquSetSymbols(src, classified, symbolValues); err != nil {
		return nil, err
	}
	return symbolValues, nil
}

func resolveEquSetSymbols(src ParsedSource, classified ClassifiedSource, symbolValues map[string]uint16) error {
	byLine := make(map[int]ClassifiedStatement, len(classified.Statements))
	for _, c := range classified.Statements {
		byLine[c.OutputLine] = c
	}

	maxPasses := len(src.Statements) + 1
	for pass := 0; pass < maxPasses; pass++ {
		changed := false
		unresolved := 0

		for _, stmt := range src.Statements {
			if stmt.Kind != StatementDirective || (stmt.Operator != "EQU" && stmt.Operator != "SET") || stmt.Label == "" {
				continue
			}
			cstmt, ok := byLine[stmt.OutputLine]
			if !ok || len(cstmt.Operands) == 0 || cstmt.Operands[0].Expr == nil {
				continue
			}
			value, known, err := evalExpr(cstmt.Operands[0].Expr, symbolValues)
			if err != nil {
				return fmt.Errorf("%s", formatDiagnosticBlock(formatStatementOrigin(stmt, src.FileDisplayNames), err.Error()))
			}
			if !known {
				unresolved++
				continue
			}
			if value < 0 || value > 0xFFFF {
				return fmt.Errorf("%s", formatDiagnosticBlock(formatStatementOrigin(stmt, src.FileDisplayNames), fmt.Sprintf("%s value out of range: %d", stmt.Operator, value)))
			}
			name := strings.ToUpper(stmt.Label)
			next := uint16(value)
			if stmt.Operator == "SET" {
				if old, exists := symbolValues[name]; !exists || old != next {
					symbolValues[name] = next
					changed = true
				}
				continue
			}
			if _, exists := symbolValues[name]; exists {
				continue
			}
			symbolValues[name] = next
			changed = true
		}

		if unresolved == 0 {
			return nil
		}
		if !changed {
			return fmt.Errorf("unable to resolve EQU/SET symbols (possible cycle or missing dependency)")
		}
	}

	return fmt.Errorf("unable to resolve EQU/SET symbols within pass limit")
}

func copySymbolValues(in map[string]uint16) map[string]uint16 {
	out := make(map[string]uint16, len(in))
	for k, v := range in {
		out[k] = v
	}
	return out
}

func evalExprWithCurrentLC(node *ExprNode, symbolValues map[string]uint16, lc uint16) (int64, bool, error) {
	old, had := symbolValues["$"]
	symbolValues["$"] = lc
	v, known, err := evalExpr(node, symbolValues)
	if had {
		symbolValues["$"] = old
	} else {
		delete(symbolValues, "$")
	}
	return v, known, err
}

func encodeDirective(stmt Statement, cstmt ClassifiedStatement, lc *uint16, symbolValues map[string]uint16, out *EncodeResult, oe *orgEntryState) (incbinBasename string, err error) {
	switch stmt.Operator {
	case "DEVICE", "INCLUDE", "END":
		return "", nil
	case "INCBIN", "BINARY":
		return encodeIncbin(stmt, lc, out)
	case "ALIGN":
		if len(cstmt.Operands) != 1 || cstmt.Operands[0].Expr == nil {
			return "", fmt.Errorf("ALIGN expects one alignment expression")
		}
		value, known, err := evalExprWithCurrentLC(cstmt.Operands[0].Expr, symbolValues, *lc)
		if err != nil {
			return "", err
		}
		if !known {
			return "", fmt.Errorf("ALIGN alignment must be known during encode")
		}
		if value < 2 || value > 8192 {
			return "", fmt.Errorf("ALIGN alignment must be between 2 and 8192, got %d", value)
		}
		if value&(value-1) != 0 {
			return "", fmt.Errorf("ALIGN alignment must be a power of 2, got %d", value)
		}
		n := value
		lcVal := int64(*lc)
		padCount64 := (n - (lcVal % n)) % n
		newLc := lcVal + padCount64
		if newLc > 0xFFFF {
			return "", fmt.Errorf("ALIGN would exceed address space (would end at %d)", newLc)
		}
		for i := int64(0); i < padCount64; i++ {
			out.Bytes = append(out.Bytes, 0x00) // NOP
		}
		*lc = uint16(newLc)
		return "", nil
	case "ENTRY":
		if oe.entryCount > 0 {
			return "", fmt.Errorf("duplicate ENTRY directive")
		}
		oe.entryCount++
		if len(cstmt.Operands) != 1 || cstmt.Operands[0].Expr == nil {
			return "", fmt.Errorf("ENTRY expects one address expression")
		}
		value, known, err := evalExprWithCurrentLC(cstmt.Operands[0].Expr, symbolValues, *lc)
		if err != nil {
			return "", err
		}
		if !known {
			return "", fmt.Errorf("ENTRY address must be known during encode")
		}
		if value < 0 || value > 0xFFFF {
			return "", fmt.Errorf("ENTRY address out of range: %d", value)
		}
		oe.entrySeen = true
		oe.entryAddr = uint16(value)
		if !oe.orgSeen {
			*lc = oe.entryAddr
		}
		return "", nil
	case "ORG":
		if oe.orgCount > 0 {
			return "", fmt.Errorf("duplicate ORG directive")
		}
		oe.orgCount++
		if len(cstmt.Operands) != 1 || cstmt.Operands[0].Expr == nil {
			return "", fmt.Errorf("ORG expects one address expression")
		}
		value, known, err := evalExprWithCurrentLC(cstmt.Operands[0].Expr, symbolValues, *lc)
		if err != nil {
			return "", err
		}
		if !known {
			return "", fmt.Errorf("ORG address must be known during encode")
		}
		if value < 0 || value > 0xFFFF {
			return "", fmt.Errorf("ORG address out of range: %d", value)
		}
		oe.orgSeen = true
		oe.orgAddr = uint16(value)
		*lc = oe.orgAddr
		return "", nil
	case "EQU":
		if stmt.Label == "" || len(cstmt.Operands) == 0 || cstmt.Operands[0].Expr == nil {
			return "", nil
		}
		value, known, err := evalExprWithCurrentLC(cstmt.Operands[0].Expr, symbolValues, *lc)
		if err != nil {
			return "", err
		}
		if known && value >= 0 && value <= 0xFFFF {
			name := strings.ToUpper(stmt.Label)
			if _, exists := symbolValues[name]; !exists {
				symbolValues[name] = uint16(value)
			}
		}
		return "", nil
	case "SET":
		if stmt.Label == "" || len(cstmt.Operands) == 0 || cstmt.Operands[0].Expr == nil {
			return "", nil
		}
		value, known, err := evalExprWithCurrentLC(cstmt.Operands[0].Expr, symbolValues, *lc)
		if err != nil {
			return "", err
		}
		if known && value >= 0 && value <= 0xFFFF {
			symbolValues[strings.ToUpper(stmt.Label)] = uint16(value)
		}
		return "", nil
	default:
		return "", fmt.Errorf("unknown directive `%s`", stmt.Operator)
	}
}

func encodeIncbin(stmt Statement, lc *uint16, out *EncodeResult) (string, error) {
	if !stmt.IncbinLoaded {
		return "", fmt.Errorf("INCBIN internal error: missing preprocessed payload")
	}
	data := stmt.IncbinPayload
	out.Bytes = append(out.Bytes, data...)
	*lc += uint16(len(data))
	return stmt.IncbinBase, nil
}

func encodeData(stmt Statement, cstmt ClassifiedStatement, lc *uint16, symbolValues map[string]uint16, out *EncodeResult) error {
	switch stmt.Operator {
	case "DEFB":
		for _, op := range cstmt.Operands {
			if op.Kind == OperandString {
				s, err := strconv.Unquote(op.Text)
				if err != nil {
					return fmt.Errorf("invalid string literal `%s`", op.Text)
				}
				for _, b := range []byte(s) {
					out.Bytes = append(out.Bytes, b)
					*lc += 1
				}
				continue
			}
			if op.Expr == nil {
				return fmt.Errorf("DEFB expects expression or string")
			}
			emitImm8OrFixup(op.Expr, *lc, symbolValues, out, stmt)
			*lc += 1
		}
		return nil
	case "DEFW":
		for _, op := range cstmt.Operands {
			if op.Expr == nil {
				return fmt.Errorf("DEFW expects expression")
			}
			emitImm16OrFixup(op.Expr, *lc, symbolValues, out, stmt)
			*lc += 2
		}
		return nil
	case "DEFS":
		if len(cstmt.Operands) < 1 || len(cstmt.Operands) > 2 {
			return fmt.Errorf("DEFS expects one or two operands")
		}
		if cstmt.Operands[0].Expr == nil {
			return fmt.Errorf("DEFS size must be an expression")
		}
		sz, known, err := evalExprWithCurrentLC(cstmt.Operands[0].Expr, symbolValues, *lc)
		if err != nil {
			return err
		}
		if !known {
			return fmt.Errorf("DEFS size must be known during encode")
		}
		if sz < 0 || sz > 65535 {
			return fmt.Errorf("DEFS size out of range: %d", sz)
		}
		n := int(sz)
		fill := int64(0)
		if len(cstmt.Operands) == 2 {
			if cstmt.Operands[1].Expr == nil {
				return fmt.Errorf("DEFS fill value must be an expression")
			}
			var ok bool
			fill, ok, err = evalExprWithCurrentLC(cstmt.Operands[1].Expr, symbolValues, *lc)
			if err != nil {
				return err
			}
			if !ok {
				return fmt.Errorf("DEFS fill value must be known during encode")
			}
			if fill < 0 || fill > 0xFF {
				return fmt.Errorf("DEFS fill value out of range: %d", fill)
			}
		}
		if int64(*lc)+int64(n) > 65536 {
			return fmt.Errorf("DEFS would exceed address space")
		}
		b := byte(fill)
		for i := 0; i < n; i++ {
			out.Bytes = append(out.Bytes, b)
		}
		*lc += uint16(n)
		return nil
	default:
		return fmt.Errorf("unknown data operator `%s`", stmt.Operator)
	}
}

func encodeOperation(stmt Statement, _ ClassifiedStatement, lc *uint16, symbolValues map[string]uint16, out *EncodeResult) (opcodeMatchInfo, error) {
	return encodeOperationWithTable(stmt, lc, symbolValues, out)
}

func encodeLD(stmt Statement, cstmt ClassifiedStatement, lc *uint16, symbolValues map[string]uint16, out *EncodeResult) error {
	if len(cstmt.Operands) != 2 {
		return fmt.Errorf("LD expects two operands")
	}
	lhs := strings.ToUpper(cstmt.Operands[0].Text)
	rhs := strings.ToUpper(cstmt.Operands[1].Text)

	if cstmt.Operands[0].Kind == OperandRegister && cstmt.Operands[1].Kind == OperandImmediate && cstmt.Operands[1].Expr != nil {
		switch lhs {
		case "BC":
			out.Bytes = append(out.Bytes, 0x01)
		case "DE":
			out.Bytes = append(out.Bytes, 0x11)
		case "HL":
			out.Bytes = append(out.Bytes, 0x21)
		case "SP":
			out.Bytes = append(out.Bytes, 0x31)
		default:
			goto next
		}
		*lc += 1
		emitImm16OrFixup(cstmt.Operands[1].Expr, *lc, symbolValues, out, stmt)
		*lc += 2
		return nil
	}

next:
	if lhs == "A" && cstmt.Operands[1].Kind == OperandMemoryRegister && rhs == "(BC)" {
		out.Bytes = append(out.Bytes, 0x0A)
		*lc += 1
		return nil
	}

	return fmt.Errorf("unsupported LD form `%s, %s`", cstmt.Operands[0].Text, cstmt.Operands[1].Text)
}

func encodeJR(stmt Statement, cstmt ClassifiedStatement, lc *uint16, symbolValues map[string]uint16, out *EncodeResult) error {
	if len(cstmt.Operands) == 1 && cstmt.Operands[0].Expr != nil {
		out.Bytes = append(out.Bytes, 0x18)
		*lc += 1
		emitRel8OrFixup(cstmt.Operands[0].Expr, *lc, *lc+1, symbolValues, out, stmt)
		*lc += 1
		return nil
	}
	if len(cstmt.Operands) == 2 && cstmt.Operands[0].Kind == OperandCondition && cstmt.Operands[1].Expr != nil {
		cc := strings.ToUpper(cstmt.Operands[0].Text)
		switch cc {
		case "NZ":
			out.Bytes = append(out.Bytes, 0x20)
		case "Z":
			out.Bytes = append(out.Bytes, 0x28)
		case "NC":
			out.Bytes = append(out.Bytes, 0x30)
		case "C":
			out.Bytes = append(out.Bytes, 0x38)
		default:
			return fmt.Errorf("unsupported JR condition `%s`", cstmt.Operands[0].Text)
		}
		*lc += 1
		emitRel8OrFixup(cstmt.Operands[1].Expr, *lc, *lc+1, symbolValues, out, stmt)
		*lc += 1
		return nil
	}
	return fmt.Errorf("unsupported JR form")
}

func emitImm8OrFixup(expr *ExprNode, lc uint16, symbolValues map[string]uint16, out *EncodeResult, stmt Statement) {
	value, known, err := evalExprWithCurrentLC(expr, symbolValues, lc)
	if err == nil && known {
		out.Bytes = append(out.Bytes, byte(value))
		return
	}
	out.Bytes = append(out.Bytes, 0x00)
	out.Fixups = append(out.Fixups, Fixup{
		Offset:      len(out.Bytes) - 1,
		Kind:        FixupImm8,
		Expr:        expr,
		SourceLine:  stmt.SourceLine,
		OutputLine:  stmt.OutputLine,
		SourceStack: stmt.SourceStack,
		RelativeTo:  lc,
	})
}

func emitImm16OrFixup(expr *ExprNode, lc uint16, symbolValues map[string]uint16, out *EncodeResult, stmt Statement) {
	value, known, err := evalExprWithCurrentLC(expr, symbolValues, lc)
	if err == nil && known {
		out.Bytes = append(out.Bytes, byte(value), byte(value>>8))
		return
	}
	out.Bytes = append(out.Bytes, 0x00, 0x00)
	out.Fixups = append(out.Fixups, Fixup{
		Offset:      len(out.Bytes) - 2,
		Kind:        FixupImm16,
		Expr:        expr,
		SourceLine:  stmt.SourceLine,
		OutputLine:  stmt.OutputLine,
		SourceStack: stmt.SourceStack,
		RelativeTo:  lc,
	})
}

func emitRel8OrFixup(expr *ExprNode, lc uint16, pcAfter uint16, symbolValues map[string]uint16, out *EncodeResult, stmt Statement) {
	value, known, err := evalExprWithCurrentLC(expr, symbolValues, lc)
	if err == nil && known {
		delta := value - int64(pcAfter)
		out.Bytes = append(out.Bytes, byte(int8(delta)))
		return
	}
	out.Bytes = append(out.Bytes, 0x00)
	out.Fixups = append(out.Fixups, Fixup{
		Offset:      len(out.Bytes) - 1,
		Kind:        FixupRel8,
		Expr:        expr,
		SourceLine:  stmt.SourceLine,
		OutputLine:  stmt.OutputLine,
		SourceStack: stmt.SourceStack,
		RelativeTo:  pcAfter,
	})
	_ = lc
}

func evalExpr(node *ExprNode, symbolValues map[string]uint16) (int64, bool, error) {
	if node == nil {
		return 0, false, fmt.Errorf("empty expression")
	}
	switch node.Kind {
	case ExprNumber:
		v, err := ParseNumberLiteral(node.Text)
		return v, err == nil, err
	case ExprSymbol:
		name := strings.ToUpper(node.Text)
		v, ok := symbolValues[name]
		if !ok {
			return 0, false, nil
		}
		return int64(v), true, nil
	case ExprUnary:
		v, known, err := evalExpr(node.Inner, symbolValues)
		if err != nil || !known {
			return 0, known, err
		}
		switch node.Text {
		case "+":
			return v, true, nil
		case "-":
			return -v, true, nil
		case "~":
			return ^v, true, nil
		default:
			return 0, false, fmt.Errorf("unsupported unary operator `%s`", node.Text)
		}
	case ExprBinary:
		lv, lknown, err := evalExpr(node.Left, symbolValues)
		if err != nil || !lknown {
			return 0, lknown, err
		}
		rv, rknown, err := evalExpr(node.Right, symbolValues)
		if err != nil || !rknown {
			return 0, rknown, err
		}
		switch node.Text {
		case "+":
			return lv + rv, true, nil
		case "-":
			return lv - rv, true, nil
		case "*":
			return lv * rv, true, nil
		case "/":
			if rv == 0 {
				return 0, false, fmt.Errorf("divide by zero")
			}
			return lv / rv, true, nil
		case "%":
			if rv == 0 {
				return 0, false, fmt.Errorf("mod by zero")
			}
			return lv % rv, true, nil
		case "&":
			return lv & rv, true, nil
		case "|":
			return lv | rv, true, nil
		case "^":
			return lv ^ rv, true, nil
		case "<<":
			return lv << rv, true, nil
		case ">>":
			return lv >> rv, true, nil
		default:
			return 0, false, fmt.Errorf("unsupported operator `%s`", node.Text)
		}
	default:
		return 0, false, fmt.Errorf("unsupported expression kind `%s`", node.Kind)
	}
}

