/*
** File:        class.c
** Description: dr2d.datatype class dispatcher
**
** OpenAmiga.org
**  This file is part of the OpenAmiga "2D structured art datatype superclass"
**
** For more information look at:
**   http://openamiga.org/?function=viewproject&projectid=51
**
*/


#include <stdbool.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdio.h>
#include "class.h"
#include "iff_dr2d.h"

uint32 ClassDispatch (Class *cl, Object *o, Msg msg);

Class *initDTClass (struct ClassBase *libBase)
{
	struct ExecIFace *IExec = libBase->IExec;
	struct IntuitionIFace *IIntuition = libBase->IIntuition;
	Class *cl = NULL;
	libBase->SuperClassBase = IExec->OpenLibrary("datatypes/drawing.datatype", 53);
	if (libBase->SuperClassBase) {
		cl = IIntuition->MakeClass(libBase->libNode.lib_Node.ln_Name, DRAWINGDTCLASS, NULL, 0, 0);
		if (cl) {
			cl->cl_Dispatcher.h_Entry = (HOOKFUNC)ClassDispatch;
			cl->cl_UserData = (uint32)libBase;
			IIntuition->AddClass(cl);
		} else {
			IExec->CloseLibrary(libBase->SuperClassBase);
		}
	}
	return libBase->DTClass = cl;
}

BOOL freeDTClass (struct ClassBase *libBase)
{
	struct ExecIFace *IExec = libBase->IExec;
	struct IntuitionIFace *IIntuition = libBase->IIntuition;
	Class *cl = libBase->DTClass;
	BOOL res = TRUE;
	if (cl) {
		res = IIntuition->FreeClass(cl);
	}
	if (res) {
		IExec->CloseLibrary(libBase->SuperClassBase);
	}
	return res;
}

static int32 ConvertDR2D (Class *cl, Object *o, struct IFFHandle *iffh);
static int32 GetDR2D (Class *cl, Object *o, struct TagItem *tags);

uint32 ClassDispatch (Class *cl, Object *o, Msg msg)
{
	struct ClassBase *libBase = (struct ClassBase *)cl->cl_UserData;
	struct DOSIFace *IDOS = libBase->IDOS;
	struct IntuitionIFace *IIntuition = libBase->IIntuition;
	uint32 ret;

	switch (msg->MethodID)
	{
		case OM_NEW:
			ret = IIntuition->IDoSuperMethodA(cl, o, msg);
			if (ret) {
				int32 error;
				error = GetDR2D(cl, (Object *)ret, ((struct opSet *)msg)->ops_AttrList);
				if (error != OK) {
					IIntuition->ICoerceMethod(cl, (Object *)ret, OM_DISPOSE);
					ret = (uint32)NULL;
					IDOS->SetIoErr(error);
				}
			}
		break;

		default:
			ret = IIntuition->IDoSuperMethodA(cl, o, msg);
		break;
	}

	return ret;
}

static int32 ConvertDR2D (Class *cl, Object *o, struct IFFHandle *iffh)
{
	struct ClassBase *libBase = (struct ClassBase *)cl->cl_UserData;
	struct ExecIFace *IExec = libBase->IExec;
	struct IntuitionIFace *IIntuition = libBase->IIntuition;
	struct DataTypesIFace *IDataTypes = libBase->IDataTypes;
	struct IFFParseIFace *IIFFParse = libBase->IIFFParse;
	int32 error = OK;
	int32 level = 0;
	ULONG ifferr = 0;
	ULONG len = 0;
	int i = 0, inc = 0;
	bool first_point = true;
	struct ddtSize ddts;
	struct ddtAttr ddta;
	struct ddtPolygon ddtp;
	struct drhd_struct drhd;
 	struct poly_struct poly;
 	struct attr_struct attr;
	Coord *points;
	struct ContextNode *cn = NULL;
	struct ColorRegister *cmap = NULL;

	/* Some reasonable values in case there's no DRHD chunk */
	drhd.XLeft = 0.0;
	drhd.XRight = 100.0;
	drhd.YTop = 0.0;
	drhd.YBot = 100.0;

	/* Should we collect the DRHD chunk instead? */
	if(IIFFParse->StopChunk(iffh, ID_DR2D, ID_DRHD)) return DTERROR_INVALID_DATA;

	if(IIFFParse->StopChunk(iffh, ID_DR2D, ID_ATTR)) return DTERROR_INVALID_DATA;
	if(IIFFParse->StopChunk(iffh, ID_DR2D, ID_CPLY)) return DTERROR_INVALID_DATA;
	if(IIFFParse->StopChunk(iffh, ID_DR2D, ID_OPLY)) return DTERROR_INVALID_DATA;
	if(IIFFParse->StopChunk(iffh, ID_DR2D, ID_CMAP)) return DTERROR_INVALID_DATA;

	while(1) {
		ifferr = IIFFParse->ParseIFF(iffh, IFFPARSE_SCAN);
		if(ifferr == IFFERR_EOC) continue;
			else if(ifferr) break;	

		cn = IIFFParse->CurrentChunk(iffh);

		if((cn) && (cn->cn_Type == ID_DR2D)) {
			switch(cn->cn_ID) {
				case ID_DRHD:
					len = IIFFParse->ReadChunkBytes(iffh, &drhd, sizeof(struct drhd_struct));

					ddts.MethodID = DDTM_SETSIZE;
					ddts.ddts_Left = drhd.XLeft;
					ddts.ddts_Right = drhd.XRight;
					ddts.ddts_Top = drhd.YTop;
					ddts.ddts_Bottom = drhd.YBot;

					IIntuition->IDoSuperMethodA(cl, o, (APTR) &ddts);
				break;

				case ID_CMAP:
					cmap = IExec->AllocVecTags(sizeof(struct ColorRegister) * cn->cn_Size,
							AVT_ClearWithValue, 0,
							TAG_DONE);
					len = IIFFParse->ReadChunkBytes(iffh, cmap, cn->cn_Size);
				break;

				case ID_ATTR:
					if(cmap == NULL) break;

					len = IIFFParse->ReadChunkBytes(iffh, &attr, sizeof(struct attr_struct));

					ddta.MethodID = DDTM_ADDATTR;
					ddta.ddta_Type = DDTA_COLOURS;

					if(attr.DashPattern == 0) {
							ddta.ddta_Data = DDTA_TRANSPARENT;
					} else {
						ddta.ddta_Data = (0xff000000) |
											(cmap[attr.EdgeValue].red << 16) |
											(cmap[attr.EdgeValue].green << 8) |
											(cmap[attr.EdgeValue].blue);
					}

					switch(attr.FillType) {
						case FT_NONE:
						case FT_OBJECTS: // not supported, treat as NONE
							ddta.ddta_Data2 = DDTA_TRANSPARENT;
						break;

						case FT_COLOR:
							ddta.ddta_Data2 = (0xff000000) |
											(cmap[attr.FillValue].red << 16) |
											(cmap[attr.FillValue].green << 8) |
											(cmap[attr.FillValue].blue);
						break;
					};

					IIntuition->IDoSuperMethodA(cl, o, (APTR) &ddta);
				break;

				case ID_CPLY:
				case ID_OPLY:
					len = IIFFParse->ReadChunkBytes(iffh, &poly, sizeof(struct poly_struct));
					points = IExec->AllocVecTags(2 * poly.NumPoints * sizeof(float),
									AVT_ClearWithValue, 0,
									TAG_DONE);
					len = IIFFParse->ReadChunkBytes(iffh, points, 2 * poly.NumPoints * sizeof(float));
					first_point = true;
					i = 0;
					while(i < poly.NumPoints) {
						if(points[2*i].bits == INDICATOR) {
							if(points[2*i + 1].bits == IND_MOVETO) {
								ddtp.MethodID = DDTM_ADDPOLY;
/*
								if ((first_point == false)) {
									if(cn->cn_ID == ID_CPLY) {
										ddtp.ddtp_Type = DDTP_CLOSE;
										IIntuition->IDoSuperMethodA(cl, o, (APTR) &ddtp);
									} else if(cn->cn_ID == ID_OPLY) {
										ddtp.ddtp_Type = DDTP_END;
										IIntuition->IDoSuperMethodA(cl, o, (APTR) &ddtp);
									}
								}
*/
								ddtp.MethodID = DDTM_ADDPOLY;
								ddtp.ddtp_Type = DDTP_MOVETO;
								ddtp.ddtp_PosX = points[2*i + 2].num;
								ddtp.ddtp_PosY = points[2*i + 3].num;

								IIntuition->IDoSuperMethodA(cl, o, (APTR) &ddtp);

								inc = 2;
								first_point = false; //test
							}
							if(points[2*i + 1].bits == IND_CURVE) {
								ddtp.MethodID = DDTM_ADDPOLY;
								if(first_point == true) {
									ddtp.ddtp_Type = DDTP_MOVETO;
									first_point = false;
								} else {
									ddtp.ddtp_Type = DDTP_LINE;
								}
								ddtp.ddtp_PosX = points[2*i + 2].num;
								ddtp.ddtp_PosY = points[2*i + 3].num;
								IIntuition->IDoSuperMethodA(cl, o, (APTR) &ddtp);

								ddtp.MethodID = DDTM_ADDPOLY;
								ddtp.ddtp_Type = DDTP_BEZIER;
								ddtp.ddtp_PosX = points[2*i + 4].num;
								ddtp.ddtp_PosY = points[2*i + 5].num;
								ddtp.ddtp_PosX2 = points[2*i + 6].num;
								ddtp.ddtp_PosY2 = points[2*i + 7].num;
								ddtp.ddtp_PosX3 = points[2*i + 8].num;
								ddtp.ddtp_PosY3 = points[2*i + 9].num;
								IIntuition->IDoSuperMethodA(cl, o, (APTR) &ddtp);
								inc = 5;
							}
						} else {
							ddtp.MethodID = DDTM_ADDPOLY;
							if(first_point == true) {
								ddtp.ddtp_Type = DDTP_MOVETO;
								first_point = false;
							} else {
								ddtp.ddtp_Type = DDTP_LINE;
							}
							ddtp.ddtp_PosX = points[2*i].num;
							ddtp.ddtp_PosY = points[2*i + 1].num;
							IIntuition->IDoSuperMethodA(cl, o, (APTR) &ddtp);

							inc = 1;
						}
						i += inc;
					}

					if(cn->cn_ID == ID_CPLY) {
						ddtp.MethodID = DDTM_ADDPOLY;
						ddtp.ddtp_Type = DDTP_CLOSE;
						IIntuition->IDoSuperMethodA(cl, o, (APTR) &ddtp);
					}

					ddtp.MethodID = DDTM_ADDPOLY;
					ddtp.ddtp_Type = DDTP_END;
					IIntuition->IDoSuperMethodA(cl, o, (APTR) &ddtp);

					IExec->FreeVec(points);
				break;

				default:
				break;
			}
		}
	}

	if(cmap) IExec->FreeVec(cmap);

	IDataTypes->SetDTAttrs(o, NULL, NULL,
		DTA_NominalHoriz,	abs(ddts.ddts_Right - ddts.ddts_Left),
		DTA_NominalVert,	abs(ddts.ddts_Bottom - ddts.ddts_Top),
		DTA_ErrorLevel,		&level,
		DTA_ErrorNumber,	&error,
		TAG_END);

	return error;
}

static int32 GetDR2D (Class *cl, Object *o, struct TagItem *tags)
{
	struct ClassBase *libBase = (struct ClassBase *)cl->cl_UserData;
	struct UtilityIFace *IUtility = libBase->IUtility;
	struct DataTypesIFace *IDataTypes = libBase->IDataTypes;
	struct IFFHandle *iffh;
	char *filename;
	int32 srctype;
	int32 error = ERROR_OBJECT_NOT_FOUND;

	filename = (char *)IUtility->GetTagData(DTA_Name, (uint32)"Untitled", tags);

	IDataTypes->GetDTAttrs(o,
		DTA_Handle,			&iffh,
		DTA_SourceType,		&srctype,
		TAG_END);

	/* Do we have everything we need? */
	if (iffh && ((srctype == DTST_FILE) || (srctype == DTST_CLIPBOARD))) {
		error = ConvertDR2D(cl, o, iffh);
	}

	if(srctype == DTST_RAM) error = OK;

	return error;
}

